\"\"\"Private OpenAI Responses API client using only the Python standard library.

Usage:
    import openai_client
    client = openai_client.OpenAIClient()
    reply = client.send_prompt(\"What is the capital of France?\")
    print(reply)

    # Streaming mode:
    for chunk in client.send_prompt(\"Tell me a story\", stream=True):
        print(chunk, end=\"\", flush=True)

Set OPENAI_API_KEY in your environment, or pass api_key= to the constructor.
\"\"\"

from __future__ import annotations

import json
import os
import ssl
import urllib.request
from typing import Any, Iterator


RESPONSES_API_URL = \"https://api.openai.com/v1/responses\"


class OpenAIClient:
    \"\"\"Minimal OpenAI Responses API client with no external dependencies.\"\"\"

    def __init__(
        self,
        api_key: str | None = None,
        base_url: str | None = None,
        timeout: float = 60.0,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\", \"\")
        self.base_url = (base_url or RESPONSES_API_URL).rstrip(\"/\")
        self.timeout = timeout

        if not self.api_key:
            raise ValueError(
                \"API key not found. Set OPENAI_API_KEY or pass api_key=.\"
            )

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def send_prompt(
        self,
        prompt: str,
        *,
        model: str = \"gpt-4o-mini\",
        instructions: str | None = None,
        temperature: float | None = None,
        max_output_tokens: int | None = None,
        stream: bool = False,
        previous_response_id: str | None = None,
    ) -> str | Iterator[str]:
        \"\"\"Send a single-turn text prompt and return the assistant's reply.

        Returns the full reply text (str) by default, or an iterator of text
        chunks when *stream* is True.
        \"\"\"
        body: dict[str, Any] = {
            \"model\": model,
            \"input\": prompt,
        }
        if instructions is not None:
            body[\"instructions\"] = instructions
        if temperature is not None:
            body[\"temperature\"] = temperature
        if max_output_tokens is not None:
            body[\"max_output_tokens\"] = max_output_tokens
        if previous_response_id is not None:
            body[\"previous_response_id\"] = previous_response_id

        if stream:
            return self._stream_response(body)
        return self._complete_response(body)

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _complete_response(self, body: dict[str, Any]) -> str:
        \"\"\"Send request and return the full response text.\"\"\"
        body = {**body, \"stream\": False}
        data = json.dumps(body).encode(\"utf-8\")
        resp = self._http_post(data)
        payload = json.loads(resp)
        return self._extract_text(payload)

    def _stream_response(self, body: dict[str, Any]) -> Iterator[str]:
        \"\"\"Send a streaming request and yield text chunks via SSE.\"\"\"
        body = {**body, \"stream\": True}
        data = json.dumps(body).encode(\"utf-8\")
        return self._read_sse_stream(data)

    def _http_post(self, data: bytes) -> bytes:
        \"\"\"Perform a single HTTP POST and return the response body bytes.\"\"\"
        req = urllib.request.Request(
            self.base_url,
            data=data,
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )
        context = ssl.create_default_context()
        with urllib.request.urlopen(req, timeout=self.timeout, context=context) as f:
            return f.read()

    def _read_sse_stream(self, data: bytes) -> Iterator[str]:
        \"\"\"Perform a streaming POST and yield text deltas from SSE events.\"\"\"
        req = urllib.request.Request(
            self.base_url,
            data=data,
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )
        context = ssl.create_default_context()
        with urllib.request.urlopen(req, timeout=self.timeout, context=context) as f:
            for line in f:
                line = line.decode(\"utf-8\").rstrip(\"\\n\\r\")
                if not line.startswith(\"data: \"):
                    continue
                payload_str = line[len(\"data: \"):]
                if payload_str == \"[DONE]\":
                    return
                try:
                    event = json.loads(payload_str)
                except json.JSONDecodeError:
                    continue
                if event.get(\"type\") == \"response.output_text.delta\":
                    delta = event.get(\"delta\", \"\")
                    if delta:
                        yield delta

    @staticmethod
    def _extract_text(payload: dict[str, Any]) -> str:
        \"\"\"Pull the final assistant text from a complete response payload.\"\"\"
        for item in payload.get(\"output\", []):
            if item.get(\"type\") == \"message\" and item.get(\"role\") == \"assistant\":
                for content in item.get(\"content\", []):
                    if content.get(\"type\") == \"output_text\":
                        return content.get(\"text\", \"\")
        return \"\"


# ------------------------------------------------------------------
# Convenience function
# ------------------------------------------------------------------

def prompt(
    text: str,
    *,
    model: str = \"gpt-4o-mini\",
    instructions: str | None = None,
    temperature: float | None = None,
    max_output_tokens: int | None = None,
    stream: bool = False,
) -> str | Iterator[str]:
    \"\"\"Quick single-call helper.  Reads OPENAI_API_KEY from the environment.\"\"\"
    client = OpenAIClient()
    return client.send_prompt(
        text,
        model=model,
        instructions=instructions,
        temperature=temperature,
        max_output_tokens=max_output_tokens,
        stream=stream,
    )
PYEOF
echo \"Done.\""

